// src/test/resources/application-test.properties
// spring.datasource.url=jdbc:h2:mem:shop;MODE=PostgreSQL

@DataJpaTest
@AutoConfigureTestDatabase(replace = Replace.NONE)
@ActiveProfiles("test")
class OrderRepositoryTest {
    @Autowired OrderRepository orders;

    @Test
    void recentDeliveriesNewestFirst() {
        // id 1: giao 01/10, id 2: chưa giao, id 3: giao 03/10, id 4: chưa giao, id 5: giao 02/10
        saveOrders(7L);
        assertThat(orders.recentDeliveries(7L))
                .extracting(Order::getId)
                .containsExactly(3L, 5L, 1L);
    }
}

fix.code:
@Query(value = """
        select * from orders
        where customer_id = :customerId
          and delivered_at is not null
        order by delivered_at desc
        limit 3""", nativeQuery = true)
List<Order> recentDeliveries(long customerId);

// Test chạy trên PostgreSQL thật, cùng phiên bản production
@TestConfiguration(proxyBeanMethods = false)
class PostgresTestConfig {
    @Bean
    @ServiceConnection
    PostgreSQLContainer postgres() {
        return new PostgreSQLContainer("postgres:17.6");
    }
}

// Cần spring-boot-testcontainers và org.testcontainers:testcontainers-postgresql.
// Schema: Flyway chạy migration lên container khi context khởi động
// (với database không nhúng, Boot không tự tạo bảng bằng ddl-auto).
@DataJpaTest
@Import(PostgresTestConfig.class)
class OrderRepositoryTest {
    @Autowired OrderRepository orders;

    @Test
    void recentDeliveriesSkipsUndeliveredOrders() {
        saveOrders(7L);
        assertThat(orders.recentDeliveries(7L))
                .extracting(Order::getId)
                .containsExactly(3L, 5L, 1L);
    }
}
